# Hindi / Gujarati text for Political Science Ch 5 lesson, sections 4-5.
TEXT_B = {
 "s4.thm.title": ("भिन्नताओं का समायोजन और हर नागरिक का सम्मान", "ભિન્નતાઓનું સમાધાન અને દરેક નાગરિકનો આદર"),
 "s4.thm.body": (
  "**सामाजिक विविधताओं में सामंजस्य:** लोकतंत्र आमतौर पर अपनी **प्रतिद्वंद्विता** चलाने की एक प्रक्रिया विकसित करते हैं। इससे **तनावों के विस्फोटक या हिंसक** होने की आशंका घटती है।\n"
  "- कोई भी समाज विभिन्न समूहों के बीच के टकराव को पूरी तरह और स्थायी रूप से नहीं सुलझा सकता। पर हम इन **भिन्नताओं का आदर** करना सीख सकते हैं और भिन्नताओं पर मोलभाव के तरीक़े विकसित कर सकते हैं। लोकतंत्र इसके लिए सबसे उपयुक्त है। **बेल्जियम** ने जातीय समूहों के बीच भिन्नताओं पर सफलतापूर्वक बातचीत की।\n"
  "- ग़ैर-लोकतांत्रिक शासन अक्सर अंदरूनी सामाजिक भिन्नताओं से आँखें मूँद लेते हैं या उन्हें **दबा** देते हैं। इसलिए सामाजिक भिन्नताओं, विभाजनों और टकरावों को सँभालना लोकतांत्रिक शासनों का **एक बड़ा गुण** है। पर **श्रीलंका** का उदाहरण याद दिलाता है कि यह परिणाम पाने के लिए लोकतंत्र को दो शर्तें पूरी करनी होती हैं:\n"
  "  1. **लोकतंत्र सिर्फ़ बहुमत की राय से चलने वाला शासन नहीं है।** बहुमत को हमेशा अल्पमत के साथ मिलकर काम करना पड़ता है ताकि सरकारें आम राय का प्रतिनिधित्व करें। बहुमत और अल्पमत की राय स्थायी नहीं होती।\n"
  "  2. **बहुमत का शासन धर्म, नस्ल या भाषा के आधार पर बहुसंख्यक समुदाय का शासन न बन जाए।** बहुमत के शासन का अर्थ है कि हर फ़ैसले या हर चुनाव में **अलग-अलग व्यक्ति और समूह बहुमत बना सकते हैं**। लोकतंत्र तभी तक लोकतंत्र रहता है जब तक **हर नागरिक को किसी न किसी अवसर पर बहुमत का हिस्सा बनने का मौक़ा** मिलता है। अगर किसी को जन्म के आधार पर बहुमत से बाहर रखा जाए, तो उस व्यक्ति या समूह के लिए लोकतांत्रिक शासन समावेशी नहीं रह जाता।\n\n"
  "**नागरिकों की गरिमा और आज़ादी:** **व्यक्ति की गरिमा और आज़ादी** को बढ़ावा देने में लोकतंत्र किसी भी दूसरे शासन से **बहुत आगे** है। हर व्यक्ति चाहता है कि उसे दूसरों से सम्मान मिले। अक्सर टकराव इसलिए होते हैं क्योंकि कुछ लोगों को लगता है कि उनके साथ उचित सम्मान का व्यवहार नहीं हुआ।\n"
  "- **महिलाओं की गरिमा:** दुनिया के अधिकतर समाज ऐतिहासिक रूप से पुरुष-प्रधान रहे। महिलाओं के लंबे संघर्षों से आज यह संवेदनशीलता आई है कि महिलाओं का सम्मान और बराबरी का व्यवहार लोकतांत्रिक समाज के ज़रूरी तत्व हैं। इसका मतलब यह नहीं कि महिलाओं के साथ हमेशा सम्मान का व्यवहार होता है, पर एक बार यह सिद्धांत मान लिया जाए, तो महिलाओं के लिए उस चीज़ के ख़िलाफ़ लड़ना आसान हो जाता है जो अब क़ानूनी और नैतिक रूप से अस्वीकार्य है। ग़ैर-लोकतांत्रिक व्यवस्था में इस अस्वीकार्यता का क़ानूनी आधार नहीं होता, क्योंकि वहाँ व्यक्तिगत आज़ादी और गरिमा के सिद्धांत का क़ानूनी और नैतिक बल नहीं होता।\n"
  "- **जातिगत असमानता:** भारत में लोकतंत्र ने **वंचित और भेदभाव झेलने वाली जातियों** के बराबर दर्जे और बराबर अवसर के दावों को **मज़बूत** किया है। जातिगत असमानता और अत्याचार के उदाहरण अब भी मिलते हैं, पर इनके पीछे अब **नैतिक और क़ानूनी आधार** नहीं है।\n\n"
  "**लोकतंत्र से अपेक्षाएँ:** लोकतंत्र हर समस्या का जादुई हल नहीं है। लोगों को लोकतंत्र के कुछ लाभ मिलते हैं तो वे और माँगते हैं और लोकतंत्र को और बेहतर बनाना चाहते हैं। इसीलिए जब हम लोगों से लोकतंत्र के कामकाज के बारे में पूछते हैं, तो उनके पास हमेशा और अपेक्षाएँ और ढेरों शिकायतें होती हैं। लोग शिकायत कर रहे हैं, यह ख़ुद **लोकतंत्र की सफलता का प्रमाण** है: यह दिखाता है कि लोगों में जागरूकता आई है और वे सत्ताधारियों तथा बड़े लोगों से अपेक्षा रखने और उन्हें आलोचनात्मक नज़र से देखने में सक्षम हुए हैं। लोकतंत्र के प्रति असंतोष की सार्वजनिक अभिव्यक्ति लोकतांत्रिक परियोजना की सफलता दिखाती है: यह लोगों को **प्रजा** से **नागरिक** बना देती है। आज अधिकतर लोग मानते हैं कि उनका **वोट** सरकार चलाने के तरीक़े और उनके अपने हितों पर **असर डालता है**।",
  "**સામાજિક વિવિધતાનું સમાધાન:** લોકશાહી સામાન્ય રીતે પોતાની **સ્પર્ધા** ચલાવવાની એક પ્રક્રિયા વિકસાવે છે. તેનાથી **તણાવો વિસ્ફોટક કે હિંસક** બનવાની શક્યતા ઘટે છે.\n"
  "- કોઈ સમાજ જુદાં જુદાં જૂથો વચ્ચેના સંઘર્ષો સંપૂર્ણ અને કાયમ માટે ઉકેલી શકતો નથી. પણ આપણે આ **ભિન્નતાઓનો આદર** કરતાં શીખી શકીએ, અને ભિન્નતાઓ પર વાટાઘાટની પદ્ધતિઓ વિકસાવી શકીએ. લોકશાહી આ માટે સૌથી યોગ્ય છે. **બેલ્જિયમે** વંશીય જૂથો વચ્ચેની ભિન્નતાઓનું સફળતાથી સમાધાન કર્યું.\n"
  "- બિનલોકશાહી શાસનો ઘણી વાર આંતરિક સામાજિક ભિન્નતાઓ તરફ આંખ આડા કાન કરે છે કે તેમને **દબાવી** દે છે. તેથી સામાજિક ભિન્નતાઓ, વિભાજનો અને સંઘર્ષોને સંભાળવાની ક્ષમતા લોકશાહી શાસનોનું **ચોક્કસ જમા પાસું** છે. પણ **શ્રીલંકા**નું ઉદાહરણ યાદ અપાવે છે કે આ પરિણામ મેળવવા લોકશાહીએ બે શરતો પૂરી કરવી પડે:\n"
  "  1. **લોકશાહી ફક્ત બહુમતીના મતથી ચાલતું શાસન નથી.** બહુમતીએ હંમેશાં લઘુમતી સાથે મળીને કામ કરવું પડે જેથી સરકારો સામાન્ય મતનું પ્રતિનિધિત્વ કરે. બહુમતી અને લઘુમતીના મત કાયમી હોતા નથી.\n"
  "  2. **બહુમતીનું શાસન ધર્મ, જાતિ કે ભાષાના આધારે બહુમતી સમુદાયનું શાસન ન બને.** બહુમતીના શાસનનો અર્થ છે કે દરેક નિર્ણય કે દરેક ચૂંટણીમાં **જુદી જુદી વ્યક્તિઓ અને જૂથો બહુમતી રચી શકે**. લોકશાહી ત્યાં સુધી જ લોકશાહી રહે છે જ્યાં સુધી **દરેક નાગરિકને ક્યારેક બહુમતીમાં રહેવાની તક** મળે. જો કોઈને જન્મના આધારે બહુમતીમાંથી બાકાત રખાય, તો તે વ્યક્તિ કે જૂથ માટે લોકશાહી શાસન સમાવેશક રહેતું નથી.\n\n"
  "**નાગરિકોનું ગૌરવ અને સ્વતંત્રતા:** **વ્યક્તિનું ગૌરવ અને સ્વતંત્રતા** વધારવામાં લોકશાહી બીજા કોઈ પણ શાસન કરતાં **ઘણી ચડિયાતી** છે. દરેક વ્યક્તિ બીજાઓ પાસેથી આદર ઇચ્છે છે. ઘણી વાર સંઘર્ષ એટલા માટે થાય છે કે કેટલાકને લાગે છે કે તેમની સાથે યોગ્ય આદરથી વર્તન થતું નથી.\n"
  "- **સ્ત્રીઓનું ગૌરવ:** દુનિયાના મોટા ભાગના સમાજો ઐતિહાસિક રીતે પુરુષપ્રધાન રહ્યા. સ્ત્રીઓના લાંબા સંઘર્ષોથી આજે એ સંવેદનશીલતા આવી છે કે સ્ત્રીઓનો આદર અને સમાન વર્તન લોકશાહી સમાજનાં જરૂરી તત્ત્વો છે. તેનો અર્થ એ નથી કે સ્ત્રીઓ સાથે હંમેશાં આદરભર્યું વર્તન થાય છે, પણ એક વાર આ સિદ્ધાંત સ્વીકારાય, પછી સ્ત્રીઓ માટે જે હવે કાનૂની અને નૈતિક રીતે અસ્વીકાર્ય છે તેની સામે લડવું સરળ બને છે. બિનલોકશાહી વ્યવસ્થામાં આ અસ્વીકાર્યતાને કાનૂની આધાર ન હોત, કારણ કે ત્યાં વ્યક્તિગત સ્વતંત્રતા અને ગૌરવના સિદ્ધાંતને કાનૂની અને નૈતિક બળ ન હોય.\n"
  "- **જ્ઞાતિગત અસમાનતા:** ભારતમાં લોકશાહીએ **વંચિત અને ભેદભાવનો ભોગ બનેલી જ્ઞાતિઓ**ના સમાન દરજ્જા અને સમાન તકના દાવાઓને **મજબૂત** કર્યા છે. જ્ઞાતિ આધારિત અસમાનતા અને અત્યાચારના કિસ્સા હજી બને છે, પણ તેમને હવે **નૈતિક અને કાનૂની આધાર** નથી.\n\n"
  "**લોકશાહી પાસેથી અપેક્ષાઓ:** લોકશાહી દરેક સમસ્યાનો જાદુઈ ઉકેલ નથી. લોકોને લોકશાહીના કેટલાક લાભ મળે ત્યારે તેઓ વધુ માગે છે અને લોકશાહીને વધુ સારી બનાવવા ઇચ્છે છે. તેથી જ્યારે આપણે લોકોને લોકશાહીના કામકાજ વિશે પૂછીએ, ત્યારે તેમની પાસે હંમેશાં વધુ અપેક્ષાઓ અને ઘણી ફરિયાદો હોય છે. લોકો ફરિયાદ કરે છે એ જ **લોકશાહીની સફળતાનો પુરાવો** છે: તે બતાવે છે કે લોકોમાં જાગૃતિ આવી છે અને તેઓ સત્તાધારીઓ પાસે અપેક્ષા રાખવા અને તેમને વિવેચનાત્મક દૃષ્ટિએ જોવા સક્ષમ બન્યા છે. લોકશાહી પ્રત્યે અસંતોષની જાહેર અભિવ્યક્તિ લોકશાહી પ્રયોગની સફળતા બતાવે છે: તે લોકોને **પ્રજા**માંથી **નાગરિક** બનાવે છે. આજે મોટા ભાગના લોકો માને છે કે તેમનો **મત** સરકાર ચલાવવાની રીત અને તેમના પોતાના હિતમાં **ફરક પાડે છે**."),
 "s4.table.title": ("लोकतंत्र का रिपोर्ट कार्ड", "લોકશાહીનું રિપોર્ટ કાર્ડ"),
 "s4.table.body": (
  "| परिणाम | लोकतंत्र का प्रदर्शन | मुख्य बात |\n|---|---|---|\n| **जवाबदेह, ज़िम्मेदार, वैध सरकार** | जवाबदेही और वैधता में बहुत अच्छा; ज़िम्मेदारी और भ्रष्टाचार में कमज़ोर | यह लोगों की अपनी सरकार है |\n"
  "| **आर्थिक संवृद्धि और विकास** | तानाशाहियों से थोड़ी कम संवृद्धि, पर अंतर नगण्य | संवृद्धि कई कारकों पर निर्भर |\n"
  "| **असमानता और ग़रीबी में कमी** | कमज़ोर: आर्थिक असमानता बढ़ रही है | राजनीतिक समानता से आर्थिक समानता नहीं आती |\n"
  "| **सामाजिक विविधता में सामंजस्य** | अच्छा: भिन्नताओं को शांति से सँभालता है | बहुमत को अल्पमत के साथ काम करना होता है |\n"
  "| **नागरिकों की गरिमा और आज़ादी** | दूसरे शासनों से बहुत आगे | महिलाओं और वंचित जातियों को बराबर दर्जा मिला |",
  "| પરિણામ | લોકશાહીનો દેખાવ | મુખ્ય મુદ્દો |\n|---|---|---|\n| **જવાબદાર, પ્રતિભાવશીલ, કાયદેસર સરકાર** | જવાબદારી અને કાયદેસરતામાં ખૂબ સારું; પ્રતિભાવ અને ભ્રષ્ટાચારમાં નબળું | તે લોકોની પોતાની સરકાર છે |\n"
  "| **આર્થિક વૃદ્ધિ અને વિકાસ** | સરમુખત્યારશાહી કરતાં થોડી ઓછી વૃદ્ધિ, પણ તફાવત નહિવત્ | વૃદ્ધિ અનેક પરિબળો પર આધારિત |\n"
  "| **અસમાનતા અને ગરીબીમાં ઘટાડો** | નબળું: આર્થિક અસમાનતા વધી રહી છે | રાજકીય સમાનતાથી આર્થિક સમાનતા આવતી નથી |\n"
  "| **સામાજિક વિવિધતાનું સમાધાન** | સારું: ભિન્નતાઓ શાંતિથી સંભાળે છે | બહુમતીએ લઘુમતી સાથે કામ કરવું પડે |\n"
  "| **નાગરિકોનું ગૌરવ અને સ્વતંત્રતા** | બીજાં શાસનો કરતાં ઘણી ચડિયાતી | સ્ત્રીઓ અને વંચિત જ્ઞાતિઓને સમાન દરજ્જો મળ્યો |"),
 "s5.memory.title": ("याद रखने की तरकीबें", "યાદ રાખવાની યુક્તિઓ"),
 "s5.memory.body": (
  "- **लोकतंत्र बेहतर क्यों: \"स-ग-फ़-ट-सु\"**: समानता, गरिमा, फ़ैसलों की गुणवत्ता, टकराव का हल, सुधार की गुंजाइश।\n- **सरकार: \"ज-ज़ि-वै\"**: जवाबदेह, ज़िम्मेदार, वैध (वैधता लोकतंत्र की सबसे पक्की ताक़त)।\n"
  "- **संवृद्धि के अंक: \"तानाशाही 4.42 > लोकतंत्र 3.95\"** (1950–2000), पर ग़रीब देशों में अंतर बहुत कम (4.34 बनाम 4.28)।\n"
  "- **संवृद्धि के कारक: \"ज-वै-स-प्रा\"**: जनसंख्या, वैश्विक स्थिति, सहयोग, प्राथमिकताएँ।\n"
  "- **विविधता की शर्तें: \"सिर्फ़ बहुमत नहीं; बहुसंख्यक समुदाय नहीं\"।**\n- **प्रजा से नागरिक**: शिकायतें यानी सफलता।",
  "- **લોકશાહી કેમ સારી: \"સ-ગૌ-નિ-સં-ભૂ\"**: સમાનતા, ગૌરવ, નિર્ણયોની ગુણવત્તા, સંઘર્ષનો ઉકેલ, ભૂલ સુધારવાની તક.\n- **સરકાર: \"જ-પ્ર-કા\"**: જવાબદાર, પ્રતિભાવશીલ, કાયદેસર (કાયદેસરતા લોકશાહીની સૌથી પાકી તાકાત).\n"
  "- **વૃદ્ધિના આંકડા: \"સરમુખત્યારશાહી 4.42 > લોકશાહી 3.95\"** (1950–2000), પણ ગરીબ દેશોમાં તફાવત ઘણો ઓછો (4.34 સામે 4.28).\n"
  "- **વૃદ્ધિનાં પરિબળો: \"વ-વૈ-સ-પ્રા\"**: વસ્તી, વૈશ્વિક પરિસ્થિતિ, સહકાર, પ્રાથમિકતાઓ.\n"
  "- **વિવિધતાની શરતો: \"ફક્ત બહુમતી નહિ; બહુમતી સમુદાય નહિ\".**\n- **પ્રજામાંથી નાગરિક**: ફરિયાદો એટલે સફળતા."),
 "s5.mistakes.title": ("आम ग़लतियाँ", "સામાન્ય ભૂલો"),
 "s5.mistakes.body": (
  "1. यह कहना कि लोकतंत्र में संवृद्धि हमेशा ज़्यादा होती है: 1950 से 2000 तक तानाशाहियों में संवृद्धि **थोड़ी ज़्यादा** रही।\n2. यह कहना कि लोकतंत्र ने आर्थिक असमानता ख़त्म कर दी: आर्थिक असमानता **बढ़ रही** है; लोकतंत्र **राजनीतिक** समानता देता है।\n"
  "3. यह कहना कि लोकतांत्रिक सरकार सबसे तेज़ फ़ैसले लेती है: यह **धीमी** है, पर इसके फ़ैसले ज़्यादा स्वीकार्य और प्रभावी हैं।\n"
  "4. यह कहना कि लोकतंत्र सिर्फ़ बहुमत का शासन है: बहुमत को **अल्पमत के साथ काम** करना होता है, और बहुमत कोई तय समुदाय नहीं होना चाहिए।\n"
  "5. यह कहना कि लोकतंत्र भ्रष्टाचार से मुक्त हैं: ऐसा नहीं, पर उनकी सरकारें **वैध** हैं।\n6. शिकायतों को विफलता मानना: शिकायतें दिखाती हैं कि लोग **नागरिक** बन गए हैं।",
  "1. કહેવું કે લોકશાહીમાં વૃદ્ધિ હંમેશાં વધુ હોય છે: 1950થી 2000 સુધી સરમુખત્યારશાહીમાં વૃદ્ધિ **થોડી વધુ** રહી.\n2. કહેવું કે લોકશાહીએ આર્થિક અસમાનતા દૂર કરી: આર્થિક અસમાનતા **વધી રહી** છે; લોકશાહી **રાજકીય** સમાનતા આપે છે.\n"
  "3. કહેવું કે લોકશાહી સરકાર સૌથી ઝડપી નિર્ણયો લે છે: તે **ધીમી** છે, પણ તેના નિર્ણયો વધુ સ્વીકાર્ય અને અસરકારક છે.\n"
  "4. કહેવું કે લોકશાહી ફક્ત બહુમતીનું શાસન છે: બહુમતીએ **લઘુમતી સાથે કામ** કરવું પડે, અને બહુમતી કોઈ નક્કી સમુદાય ન હોવો જોઈએ.\n"
  "5. કહેવું કે લોકશાહી ભ્રષ્ટાચારથી મુક્ત છે: એવું નથી, પણ તેની સરકારો **કાયદેસર** છે.\n6. ફરિયાદોને નિષ્ફળતા માનવી: ફરિયાદો બતાવે છે કે લોકો **નાગરિક** બન્યા છે."),
 "s5.tip.title": ("कक्षा में करके देखें", "વર્ગમાં કરી જુઓ"),
 "s5.tip.body": (
  "बोर्ड पर भारत में लोकतंत्र का पाँच पंक्तियों वाला 'रिपोर्ट कार्ड' बनाइए (जवाबदेही, आर्थिक संवृद्धि, असमानता, सामाजिक विविधता, गरिमा)। समूहों से हर पंक्ति के लिए एक प्रमाण के साथ ग्रेड दिलवाइए, फिर ग्रेडों की तुलना करके चर्चा कीजिए कि वे अलग क्यों हैं।",
  "બોર્ડ પર ભારતમાં લોકશાહીનું પાંચ હરોળનું 'રિપોર્ટ કાર્ડ' બનાવો (જવાબદારી, આર્થિક વૃદ્ધિ, અસમાનતા, સામાજિક વિવિધતા, ગૌરવ). જૂથોને દરેક હરોળ માટે એક પુરાવા સાથે ગ્રેડ આપવા કહો, પછી ગ્રેડની સરખામણી કરી ચર્ચા કરો કે તે જુદા કેમ છે."),
 "s5.reflection.title": ("सोचिए और समझाइए", "વિચારો અને સમજાવો"),
 "s5.reflection.body": (
  "अपने इलाक़े की कोई एक सार्वजनिक समस्या सोचिए (सड़क, पानी, स्कूल)। उसे हल कराने के लिए नागरिक कौन-सा लोकतांत्रिक साधन इस्तेमाल कर सकता है: वोट, सूचना का अधिकार, याचिका, मीडिया या स्थानीय प्रतिनिधि?",
  "તમારા વિસ્તારની કોઈ એક જાહેર સમસ્યા વિચારો (રસ્તા, પાણી, શાળા). તેને ઉકેલાવવા નાગરિક કયું લોકશાહી સાધન વાપરી શકે: મત, માહિતી અધિકાર, અરજી, માધ્યમો કે સ્થાનિક પ્રતિનિધિ?"),
 "s5.connection.title": ("आगे कहाँ", "આગળ ક્યાં"),
 "s5.connection.body": (
  "- **अध्याय 1 (सत्ता की साझेदारी):** बेल्जियम, श्रीलंका और विविधता का समायोजन।\n- **अध्याय 3 (जाति, धर्म और लैंगिक मसले):** महिलाओं और वंचित जातियों की गरिमा।\n"
  "- **अर्थशास्त्र अध्याय 1 (विकास):** संवृद्धि, आय और विकास के दूसरे लक्ष्य।",
  "- **પ્રકરણ 1 (સત્તાની ભાગીદારી):** બેલ્જિયમ, શ્રીલંકા અને વિવિધતાનું સમાધાન.\n- **પ્રકરણ 3 (જાતિ, ધર્મ અને જ્ઞાતિ):** સ્ત્રીઓ અને વંચિત જ્ઞાતિઓનું ગૌરવ.\n"
  "- **અર્થશાસ્ત્ર પ્રકરણ 1 (વિકાસ):** વૃદ્ધિ, આવક અને વિકાસનાં બીજાં લક્ષ્યો."),
 "s5.mastery.title": ("महारत चुनौती", "નિપુણતા પડકાર"),
 "s5.mastery.body": (
  "'लोकतंत्र शासन के किसी भी दूसरे रूप से बेहतर है।' लोकतंत्र के परिणामों के आधार पर लगभग 120 शब्दों में इस कथन का मूल्यांकन कीजिए।\n\n"
  "**आदर्श उत्तर:** लोकतंत्र जवाबदेह, ज़िम्मेदार और वैध सरकार देता है: नागरिक नियमित, स्वतंत्र और निष्पक्ष चुनावों, खुली बहस और सूचना के अधिकार से अपने शासक चुनते और नियंत्रित करते हैं। इसके फ़ैसले धीमे हो सकते हैं, पर ज़्यादा स्वीकार्य और प्रभावी होते हैं। "
  "यह समूहों को शांति से प्रतिद्वंद्विता करने देकर सामाजिक विविधता को समेटता है, जैसे बेल्जियम में, और महिलाओं तथा वंचित जातियों समेत व्यक्तियों की गरिमा और आज़ादी बढ़ाता है। "
  "पर लोकतंत्र आर्थिक असमानता और ग़रीबी घटाने में अच्छा नहीं रहा, और 1950 से 2000 तक तानाशाहियों में संवृद्धि थोड़ी ज़्यादा रही, हालाँकि ग़रीब देशों में अंतर नगण्य है। "
  "कुल मिलाकर लोकतंत्र बेहतर है क्योंकि यह लोगों की अपनी सरकार है और ग़लतियाँ सुधारने देता है।",
  "'લોકશાહી શાસનના બીજા કોઈ પણ સ્વરૂપ કરતાં સારી છે.' લોકશાહીનાં પરિણામોના આધારે આશરે 120 શબ્દોમાં આ વિધાનનું મૂલ્યાંકન કરો.\n\n"
  "**આદર્શ જવાબ:** લોકશાહી જવાબદાર, પ્રતિભાવશીલ અને કાયદેસર સરકાર આપે છે: નાગરિકો નિયમિત, મુક્ત અને ન્યાયી ચૂંટણીઓ, ખુલ્લી ચર્ચા અને માહિતીના અધિકાર દ્વારા પોતાના શાસકો પસંદ કરે છે અને નિયંત્રિત કરે છે. તેના નિર્ણયો ધીમા હોઈ શકે, પણ વધુ સ્વીકાર્ય અને અસરકારક હોય છે. "
  "તે જૂથોને શાંતિથી સ્પર્ધા કરવા દઈ સામાજિક વિવિધતાને સમાવે છે, જેમ બેલ્જિયમમાં, અને સ્ત્રીઓ તથા વંચિત જ્ઞાતિઓ સહિત વ્યક્તિઓનું ગૌરવ અને સ્વતંત્રતા વધારે છે. "
  "પણ લોકશાહી આર્થિક અસમાનતા અને ગરીબી ઘટાડવામાં સફળ રહી નથી, અને 1950થી 2000 સુધી સરમુખત્યારશાહીમાં વૃદ્ધિ થોડી વધુ રહી, જોકે ગરીબ દેશોમાં તફાવત નહિવત્ છે. "
  "એકંદરે લોકશાહી વધુ સારી છે કારણ કે તે લોકોની પોતાની સરકાર છે અને ભૂલો સુધારવા દે છે."),
 "s5.summary.title": ("अध्याय सारांश", "પ્રકરણ સારાંશ"),
 "s5.summary.body": (
  "- लोकतंत्र समानता और गरिमा बढ़ाता है, फ़ैसले सुधारता है, टकराव सुलझाता है और ग़लतियाँ सुधारने देता है; यह परिस्थितियाँ बनाता है, जिनका नागरिकों को इस्तेमाल करना होता है।\n"
  "- यह जवाबदेह, ज़िम्मेदार और वैध सरकार देता है; फ़ैसले धीमे पर ज़्यादा स्वीकार्य होते हैं, और पारदर्शिता इसमें निहित है।\n"
  "- तानाशाहियों में संवृद्धि थोड़ी तेज़ रही (1950–2000), पर संवृद्धि कई कारकों पर निर्भर है और अंतर कम है।\n"
  "- लोकतंत्र राजनीतिक समानता देता है, पर आर्थिक असमानता और ग़रीबी गंभीर समस्याएँ बनी हुई हैं।\n"
  "- यह सामाजिक विविधता को तभी समेटता है जब बहुमत अल्पमत के साथ काम करे और कोई समुदाय स्थायी बहुमत न हो।\n"
  "- गरिमा और आज़ादी बढ़ाने में यह बहुत आगे है; लोकतंत्र की शिकायतें इसकी सफलता दिखाती हैं, क्योंकि लोग नागरिक बन जाते हैं।",
  "- લોકશાહી સમાનતા અને ગૌરવ વધારે છે, નિર્ણયો સુધારે છે, સંઘર્ષો ઉકેલે છે અને ભૂલો સુધારવા દે છે; તે પરિસ્થિતિ ઊભી કરે છે, જેનો નાગરિકોએ ઉપયોગ કરવો પડે.\n"
  "- તે જવાબદાર, પ્રતિભાવશીલ અને કાયદેસર સરકાર આપે છે; નિર્ણયો ધીમા પણ વધુ સ્વીકાર્ય હોય છે, અને પારદર્શિતા તેમાં સમાયેલી છે.\n"
  "- સરમુખત્યારશાહીમાં વૃદ્ધિ થોડી ઝડપી રહી (1950–2000), પણ વૃદ્ધિ અનેક પરિબળો પર આધારિત છે અને તફાવત ઓછો છે.\n"
  "- લોકશાહી રાજકીય સમાનતા આપે છે, પણ આર્થિક અસમાનતા અને ગરીબી ગંભીર સમસ્યાઓ છે.\n"
  "- તે સામાજિક વિવિધતાને ત્યારે જ સમાવે છે જ્યારે બહુમતી લઘુમતી સાથે કામ કરે અને કોઈ સમુદાય કાયમી બહુમતી ન હોય.\n"
  "- ગૌરવ અને સ્વતંત્રતા વધારવામાં તે ઘણી આગળ છે; લોકશાહી વિશેની ફરિયાદો તેની સફળતા બતાવે છે, કારણ કે લોકો નાગરિક બને છે."),
 "s5.examtips.title": ("बोर्ड परीक्षा के सुझाव", "બોર્ડ પરીક્ષા માટેની ટિપ્સ"),
 "s5.examtips.body": (
  "- 2025-26 के प्रतिदर्श प्रश्न-पत्र में पूछा गया कि लोकतंत्र शांतिपूर्ण और सौहार्दपूर्ण जीवन देता है, इसके तीन तर्क दीजिए (सामाजिक विभाजनों का समायोजन, प्रतिद्वंद्विता की प्रक्रिया, भिन्नताओं का आदर, बहुमत का अल्पमत के साथ काम करना, कोई स्थायी बहुसंख्यक समुदाय नहीं)।\n"
  "- 3/5 अंक के पसंदीदा प्रश्न: जवाबदेह, ज़िम्मेदार और वैध सरकार; आर्थिक परिणाम; विविधता समेटने की शर्तें; गरिमा और आज़ादी।\n"
  "- सामाजिक विविधता पर लिखते समय अध्याय 1 के बेल्जियम और श्रीलंका के उदाहरण दें।",
  "- 2025-26ના નમૂનાના પ્રશ્નપત્રમાં પુછાયું કે લોકશાહી શાંતિપૂર્ણ અને સુમેળભર્યું જીવન આપે છે તેની ત્રણ દલીલો આપો (સામાજિક વિભાજનોનું સમાધાન, સ્પર્ધાની પ્રક્રિયા, ભિન્નતાઓનો આદર, બહુમતીનું લઘુમતી સાથે કામ, કોઈ કાયમી બહુમતી સમુદાય નહિ).\n"
  "- 3/5 ગુણના પ્રિય પ્રશ્નો: જવાબદાર, પ્રતિભાવશીલ અને કાયદેસર સરકાર; આર્થિક પરિણામો; વિવિધતા સમાવવાની શરતો; ગૌરવ અને સ્વતંત્રતા.\n"
  "- સામાજિક વિવિધતા પર લખતી વખતે પ્રકરણ 1નાં બેલ્જિયમ અને શ્રીલંકાનાં ઉદાહરણ આપો."),
 "s5.flash1.front": ("वैध सरकार क्या है?", "કાયદેસર સરકાર શું છે?"),
 "s5.flash1.back": ("ऐसी सरकार जो लोगों की अपनी सरकार है, उनके द्वारा चुनी हुई; लोकतंत्र धीमा या कम कुशल हो सकता है, पर वैध है।", "એવી સરકાર જે લોકોની પોતાની છે, તેમણે ચૂંટેલી; લોકશાહી ધીમી કે ઓછી કાર્યક્ષમ હોઈ શકે, પણ કાયદેસર છે."),
 "s5.flash2.front": ("लोकतंत्र में पारदर्शिता क्या है?", "લોકશાહીમાં પારદર્શિતા શું છે?"),
 "s5.flash2.back": ("नागरिकों का फ़ैसले की प्रक्रिया की जाँच करने का अधिकार और साधन, जैसे सूचना के अधिकार से।", "નાગરિકોનો નિર્ણય પ્રક્રિયા ચકાસવાનો અધિકાર અને સાધનો, જેમ કે માહિતી અધિકાર દ્વારા."),
 "s5.flash3.front": ("आर्थिक विकास किन कारकों पर निर्भर करता है?", "આર્થિક વિકાસ કયાં પરિબળો પર આધાર રાખે છે?"),
 "s5.flash3.back": ("जनसंख्या का आकार, वैश्विक स्थिति, दूसरे देशों से सहयोग और देश की आर्थिक प्राथमिकताएँ।", "વસ્તીનું કદ, વૈશ્વિક પરિસ્થિતિ, બીજા દેશોનો સહકાર અને દેશની આર્થિક પ્રાથમિકતાઓ."),
 "s5.flash4.front": ("सामाजिक विविधता समेटने के लिए लोकतंत्र की दो शर्तें क्या हैं?", "સામાજિક વિવિધતા સમાવવા લોકશાહીની બે શરતો કઈ છે?"),
 "s5.flash4.back": ("यह सिर्फ़ बहुमत की राय का शासन नहीं (बहुमत अल्पमत के साथ काम करे), और बहुमत का शासन बहुसंख्यक समुदाय का शासन न बने।", "તે ફક્ત બહુમતીના મતનું શાસન નથી (બહુમતી લઘુમતી સાથે કામ કરે), અને બહુમતીનું શાસન બહુમતી સમુદાયનું શાસન ન બને."),
}
